package com.cni.evidence; import com.cni.casefile.CaseRepository; import com.cni.casefile.CaseAccessService; import com.cni.user.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.security.MessageDigest; import java.time.Instant; import java.util.*;
@RestController @Transactional @RequestMapping("/api/v1/evidence") @RequiredArgsConstructor public class EvidenceController{private final EvidenceRepository repo;private final CaseRepository cases;private final CaseAccessService access;private final UserRepository users;@Value("${app.storage.path:./data/uploads}")private String storage;@GetMapping public List<Map<String,Object>> list(@RequestParam UUID caseId,Authentication a){access.require(caseId,a);return repo.findByInvestigationCase_IdOrderByCreatedAtDesc(caseId).stream().map(this::view).toList();}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public Map<String,Object> upload(@RequestParam UUID caseId,@RequestParam MultipartFile file,Authentication a)throws Exception{if(file.isEmpty())throw new IllegalArgumentException("Empty file");var c=access.require(caseId,a);var u=users.findByUsername(a.getName()).orElseThrow();Path dir=Paths.get(storage).toAbsolutePath().normalize();Files.createDirectories(dir);var stored=UUID.randomUUID()+"-"+Paths.get(Objects.requireNonNullElse(file.getOriginalFilename(),"upload.bin")).getFileName();var target=dir.resolve(stored);file.transferTo(target);var sha=MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(target));var hex=HexFormat.of().formatHex(sha);return view(repo.save(EvidenceFile.builder().investigationCase(c).uploadedBy(u).originalName(file.getOriginalFilename()).storedName(stored.toString()).contentType(file.getContentType()).sizeBytes(file.getSize()).sha256(hex).createdAt(Instant.now()).build()));}private Map<String,Object> view(EvidenceFile e){return Map.of("id",e.getId(),"caseId",e.getInvestigationCase().getId(),"originalName",e.getOriginalName(),"contentType",Objects.toString(e.getContentType(),"application/octet-stream"),"sizeBytes",e.getSizeBytes(),"sha256",e.getSha256(),"uploadedBy",e.getUploadedBy().getFullName(),"createdAt",e.getCreatedAt());}}
